import{F as t}from"./chunks/FigureContainer.zzqKkC_T.js";import{H as p}from"./chunks/HighLightText.xFkhFkD_.js";import{R as r}from"./chunks/ResourceCard.2BfY0ozu.js";import{c as d,o,a as n,b as e,d as i,e as a,w as l}from"./chunks/vitepress-theme-teek.BmVBWFw5.js";/* empty css                                                                               *//* empty css                                                             */const T=JSON.parse('{"title":"模型训练范式","description":"解析大模型训练全流程：预训练阶段的自监督学习与数据工程，对齐阶段的 SFT、RLHF 与 DPO 技术原理，以及 Scaling Laws 对训练策略的指导意义。","frontmatter":{"date":"2026-06-29T09:49:21.000Z","title":"模型训练范式","tldr":"预训练打基础，SFT 学对话，RLHF/DPO 做对齐——LLM 训练是一条三阶段流水线。","description":"解析大模型训练全流程：预训练阶段的自监督学习与数据工程，对齐阶段的 SFT、RLHF 与 DPO 技术原理，以及 Scaling Laws 对训练策略的指导意义。","tags":["概念","预训练","微调","对齐"],"categories":["大模型基础","训练与优化"],"permalink":"/llm-basic/training-optimization"},"headers":[],"relativePath":"llm-basic/training-optimization.md","filePath":"22.大模型基础/03.训练与优化/01.模型训练范式.md"}'),b={name:"llm-basic/training-optimization.md"},v=Object.assign(b,{setup(c){return(u,s)=>(o(),d("div",null,[s[17]||(s[17]=n("h1",{id:"模型训练范式",tabindex:"-1"},[a("模型训练范式 "),n("a",{class:"header-anchor",href:"#模型训练范式","aria-label":"Permalink to “模型训练范式”"},"​")],-1)),s[18]||(s[18]=n("blockquote",null,[n("p",null,[n("strong",null,"摘要"),a(": 大语言模型的训练遵循一条从通用知识灌输到人类偏好对齐的流水线范式。预训练阶段通过自监督学习（Next-Token Prediction/MLM）在海量语料上构建基础能力，其效果受 Scaling Laws 支配——模型性能与参数量、数据量和算力呈幂律关系。对齐阶段依次通过监督微调（SFT）赋予模型指令遵循能力，再通过 RLHF 或 DPO 将人类偏好注入模型，使其输出符合有用性、真实性和无害性标准。理解这条训练流水线，是评估模型能力边界和选择微调策略的基础。")])],-1)),e(r,{resource:{name:"图集速览：模型训练范式——从海量知识灌输到人类价值对齐",description:"如果你对模型训练范式还比较陌生，建议先读这篇图集速览。用可视化图片集合和要点摘要，帮你快速理清预训练、微调与对齐的完整流水线。",url:"https://mp.weixin.qq.com/s/R7l-2Bm7MCMx182RxfJRlQ",type:"article",tags:["预训练","微调","对齐","RLHF"]}}),s[19]||(s[19]=i(`<h2 id="_1-引言" tabindex="-1">1. 引言 <a class="header-anchor" href="#_1-引言" aria-label="Permalink to “1. 引言”">​</a></h2><p>现代<strong>大语言模型的训练并非一蹴而就，而是一条环环相扣的精密流水线</strong>。从海量语料中的知识积累，到人类偏好的精准对齐，每个阶段都在塑造模型的能力与边界。理解这条训练流水线，正是解锁 LLM 核心能力的关键。</p><h2 id="_2-pre-training-预训练" tabindex="-1">2. Pre-training（预训练） <a class="header-anchor" href="#_2-pre-training-预训练" aria-label="Permalink to “2. Pre-training（预训练）”">​</a></h2><p>预训练是 LLM 训练的基石，也是资源消耗最密集的阶段。如果将 LLM 比作一位学生，预训练就相当于&quot;通读人类所有典籍&quot;的奠基过程——在浩瀚语料中习得语言规律与世界知识，为后续能力发展打下坚实基础。</p><h3 id="_2-1-自监督学习-next-token-prediction-mlm" tabindex="-1">2.1 自监督学习（Next-Token Prediction / MLM） <a class="header-anchor" href="#_2-1-自监督学习-next-token-prediction-mlm" aria-label="Permalink to “2.1 自监督学习（Next-Token Prediction / MLM）”">​</a></h3><p>预训练的核心思想被称为<strong>自监督学习</strong>：不需要人工标注，模型从数据本身自动构造监督信号。</p><p><strong>GPT 系列模型的 Next-Token Prediction</strong></p><p>GPT 系列采用自回归（Autoregressive）方式。给定前文，模型预测下一个 token：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>输入:  &quot;中国的首都是&quot;</span></span>
<span class="line"><span>模型预测: &quot;北&quot;  → 输入变为 &quot;中国的首都是北&quot;</span></span>
<span class="line"><span>继续预测: &quot;京&quot;  → 输入变为 &quot;中国的首都是北京&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>损失函数: 交叉熵损失 = -log P(正确token | 前文tokens)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这就是 <strong>Causal Language Modeling（CLM）</strong>，每个位置只能看到它前面的 token（因果注意力掩码）。</p><p><strong>BERT 系列的 Masked Language Modeling（MLM）</strong></p><p>BERT 采用另一种思路——随机遮住 15% 的 token，让模型根据上下文填空：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>原句: &quot;猫坐在垫子上&quot;</span></span>
<span class="line"><span>遮罩: &quot;猫坐在 [MASK] 上&quot;</span></span>
<span class="line"><span>模型需预测: [MASK] = &quot;垫子&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>损失只在被遮罩的位置计算</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">关键区别</p><p>MLM 是双向的（能看到前后文），CLM 是单向的（只看前文）。现代大模型几乎都采用 CLM，因为它更自然地适配对话生成任务。</p></div><h3 id="_2-2-训练数据规模与质量" tabindex="-1">2.2 训练数据规模与质量 <a class="header-anchor" href="#_2-2-训练数据规模与质量" aria-label="Permalink to “2.2 训练数据规模与质量”">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">关键理解</p><p>&quot;Garbage in, garbage out&quot; 在预训练中体现得尤为深刻。</p><p>一个常见的经验是：<strong>用更少但更好的数据训练，效果好于用更多但更差的数据训练</strong>。</p></div><p>预训练数据量级用<strong>万亿 token</strong>衡量：</p><table tabindex="0"><thead><tr><th>模型</th><th>训练数据量</th></tr></thead><tbody><tr><td>GPT-3 (2020)</td><td>~300B tokens</td></tr><tr><td>LLaMA 2 (2023)</td><td>2T tokens</td></tr><tr><td>DeepSeek-V3 (2024)</td><td>14.8T tokens</td></tr></tbody></table><p>但<strong>质量比数量更重要</strong>,LLaMA 2 的技术报告明确指出了这一点——2T 高质量 token 的效果远超更多低质量 token。</p><p>数据处理的典型流程：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>原始网页爬取 → 语言过滤 → 去重(MinHash) → 启发式清洗</span></span>
<span class="line"><span>→ 基于模型的质量打分 → 去隐私(PII移除) → 最终语料</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_2-3-scaling-laws" tabindex="-1">2.3 Scaling Laws <a class="header-anchor" href="#_2-3-scaling-laws" aria-label="Permalink to “2.3 Scaling Laws”">​</a></h3><p>2022 年，DeepMind 的 Chinchilla 论文提出了一个关键发现：在给定计算预算下，<strong>模型参数量和训练数据量应该等比例增长</strong>。</p><p>在此之前，大家习惯的做法是把模型越做越大（像 GPT-3 有 175B 参数但只训练了 300B token）。Chinchilla 定律指出这是<strong>欠训练</strong>（undertrained）：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Chinchilla 最优:  参数量 ∝ 训练token数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例如: 你有 10× 的计算预算</span></span>
<span class="line"><span>  正确做法: 模型扩大 ~3.16×, 数据扩大 ~3.16×</span></span>
<span class="line"><span>  常见错误: 模型扩大 10×, 数据不变</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>更直觉的理解：不要只给模型&quot;更大的大脑&quot;，要同时给它&quot;更多的知识&quot;。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>计算预算 C 的分配:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                 参数量 (N)              训练数据量 (D)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Chinchilla:  N_opt ∝ C^0.5           D_opt ∝ C^0.5</span></span>
<span class="line"><span>过往实践:    偏大(如C^0.73)            偏小(C^0.27)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这意味着: 像 LLaMA 2-7B 用 2T token 训练的 &quot;小模型大数据&quot;</span></span>
<span class="line"><span>策略, 正是 Chinchilla 定律的成功应用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_2-4-分布式训练概览" tabindex="-1">2.4 分布式训练概览 <a class="header-anchor" href="#_2-4-分布式训练概览" aria-label="Permalink to “2.4 分布式训练概览”">​</a></h3><p>当模型规模超出单张 GPU 的显存容量时，就需要采用分布式训练技术。目前主要有三种并行策略：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌──────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    分布式训练策略                       │</span></span>
<span class="line"><span>├──────────────┬──────────────┬─────────────────────────┤</span></span>
<span class="line"><span>│  数据并行(DP) │  模型并行(MP) │     ZeRO (DeepSpeed)    │</span></span>
<span class="line"><span>├──────────────┼──────────────┼─────────────────────────┤</span></span>
<span class="line"><span>│ 每张卡有完整  │ 模型切分到    │ ZeRO-1: 切分优化器状态    │</span></span>
<span class="line"><span>│ 模型副本      │ 多张卡上      │ ZeRO-2: +切分梯度         │</span></span>
<span class="line"><span>│ 各自算自己的   │              │ ZeRO-3: +切分参数         │</span></span>
<span class="line"><span>│ batch数据     │ 流水线并行    │                         │</span></span>
<span class="line"><span>│ 最后聚合梯度  │ 张量并行      │ 最小化显存占用           │</span></span>
<span class="line"><span>└──────────────┴──────────────┴─────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><ul><li><strong>数据并行</strong>：每张 GPU 持有完整模型副本，各自处理不同数据批次，然后同步梯度。显存要求高但实现简单</li><li><strong>流水线并行</strong>：按层切分模型（前几层在 GPU-0，后几层在 GPU-1）</li><li><strong>张量并行</strong>：把单层内的矩阵运算切到多张卡上</li><li><strong>ZeRO</strong>：DeepSpeed 的核心技术，通过在数据并行的各卡之间切分优化器状态、梯度和参数来消除冗余。ZeRO-3 可以让 13B 模型在 4 张 24G 显存的消费级显卡上训练</li></ul><p>实际训练中往往<strong>三者结合</strong>：3D 并行 = 数据并行 + 流水线并行 + 张量并行。</p><h2 id="_3-fine-tuning-微调" tabindex="-1">3. Fine-Tuning：微调 <a class="header-anchor" href="#_3-fine-tuning-微调" aria-label="Permalink to “3. Fine-Tuning：微调”">​</a></h2><h3 id="_3-1-什么是微调" tabindex="-1">3.1 什么是微调？ <a class="header-anchor" href="#_3-1-什么是微调" aria-label="Permalink to “3.1 什么是微调？”">​</a></h3><p><strong>微调（Fine-Tuning）是在预训练模型的基础上，用特定领域或任务的数据继续训练模型，使其适应下游任务。</strong> 它是连接「通用基础模型」和「实际应用」的桥梁。</p>`,35)),n("p",null,[s[1]||(s[1]=n("strong",null,"核心思想",-1)),s[2]||(s[2]=a("：模型在预训练阶段已经学到了丰富的语言知识和通用能力（语法、常识、推理模式等），",-1)),e(p,{bold:"",type:"note"},{default:l(()=>[...s[0]||(s[0]=[a("微调只需要用少量任务数据就能唤醒和引导这些能力，而不需要从头训练。",-1)])]),_:1})]),e(t,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/training-optimization/fine_tuning_tips.png",caption:""}),s[20]||(s[20]=i(`<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>预训练模型（通用能力） + 任务数据（特定行为）→ 微调 → 专用模型</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_3-2-fine-tuning-sft-概念澄清" tabindex="-1">3.2 Fine-Tuning ≠ SFT：概念澄清 <a class="header-anchor" href="#_3-2-fine-tuning-sft-概念澄清" aria-label="Permalink to “3.2 Fine-Tuning ≠ SFT：概念澄清”">​</a></h3><p>一个常见的混淆是把 Fine-Tuning 等同于 SFT。实际上，<strong>SFT 只是 Fine-Tuning 的众多形式之一</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Fine-Tuning（微调）——大类，指所有「在预训练模型上继续训练以适应特定任务」的方法</span></span>
<span class="line"><span>├── 按训练目标分类：</span></span>
<span class="line"><span>│   ├── SFT (Supervised Fine-Tuning)           ← 监督学习形式（指令-回答对）</span></span>
<span class="line"><span>│   ├── RLHF (Reinforcement Learning from Human Feedback)  ← 强化学习形式</span></span>
<span class="line"><span>│   └── DPO (Direct Preference Optimization)   ← 偏好学习形式（DPO 也是一种微调）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 按参数规模分类：</span></span>
<span class="line"><span>│   ├── 全量微调 (Full Fine-Tuning)             ← 更新所有参数</span></span>
<span class="line"><span>│   └── 参数高效微调 (PEFT, Parameter-Efficient Fine-Tuning)</span></span>
<span class="line"><span>│       ├── LoRA / QLoRA                       ← 低秩适配</span></span>
<span class="line"><span>│       ├── Adapter                             ← 插入小型适配层</span></span>
<span class="line"><span>│       ├── Prefix Tuning                       ← 学习可训练前缀</span></span>
<span class="line"><span>│       └── Prompt Tuning                       ← 学习软提示向量</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── 按数据形式分类：</span></span>
<span class="line"><span>    ├── 指令微调 (Instruction Tuning)            ← SFT 的一种特化</span></span>
<span class="line"><span>    ├── 对话微调 (Chat Tuning)                   ← 多轮对话数据</span></span>
<span class="line"><span>    └── 领域微调 (Domain Adaptation)             ← 垂直领域数据</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>只用 SFT 来解释 Fine-Tuning，会遗漏两大块：</p>`,5)),n("ol",null,[n("li",null,[s[4]||(s[4]=n("strong",null,"RLHF/DPO 也是微调",-1)),s[5]||(s[5]=a("。它们同样是在预训练模型上继续训练、更新模型参数，",-1)),e(p,{bold:"",type:"note"},{default:l(()=>[...s[3]||(s[3]=[a("只是优化目标从「拟合标签」变成了「最大化人类偏好分数」。严格来说，RLHF/DPO 属于一种特殊的 Fine-Tuning。",-1)])]),_:1})]),s[6]||(s[6]=n("li",null,[n("strong",null,"实践中更常用的是 PEFT 而非全量微调"),a("。过去所谓「微调」默认是全量更新参数，但现在 7B/70B 规模下全量微调太贵，LoRA 等轻量级方法才是工程主流——而 SFT 这个术语默认暗示的是全量监督微调。")],-1))]),s[21]||(s[21]=i('<h3 id="_3-3-微调-vs-预训练的本质差异" tabindex="-1">3.3 微调 vs 预训练的本质差异 <a class="header-anchor" href="#_3-3-微调-vs-预训练的本质差异" aria-label="Permalink to “3.3 微调 vs 预训练的本质差异”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>预训练 (Pre-training)</th><th>微调 (Fine-Tuning)</th></tr></thead><tbody><tr><td>数据量</td><td>数万亿 token</td><td><strong>数百~数万条样本（取决于任务复杂度）</strong></td></tr><tr><td>计算量</td><td>数万 GPU·月</td><td><strong>数 GPU·小时（全量）或 数 GPU·分钟（LoRA）</strong></td></tr><tr><td>学习率</td><td>较高（如 3e-4）</td><td>较低（如 2e-5 或更低）</td></tr><tr><td>训练轮数</td><td>通常 1 个 epoch（避免过拟合）</td><td>1-5 个 epoch（数据少，需要多轮）</td></tr><tr><td>目标</td><td>学习「世界知识」——语言结构、常识、推理模式</td><td><strong>学习「特定行为」——交互格式、任务规则、偏好对齐</strong></td></tr><tr><td>数据形式</td><td>任意自然文本（网页、书籍、代码）</td><td><strong>结构化数据（指令-回答、偏好对、对话等）</strong></td></tr><tr><td>泛化目标</td><td>通用语言能力</td><td><strong>任务特定表现</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">一个比喻：</p><p>预训练是让一个学生读完整个图书馆（积累通识知识），微调是教他考某一门科目的答题技巧（聚焦特定行为）。学生不是因为微调才有了知识，而是微调教会了他如何把已有的知识以正确的形式表达出来。</p></div><h3 id="_3-4-全量微调-vs-参数高效微调-peft" tabindex="-1">3.4 全量微调 vs 参数高效微调（PEFT） <a class="header-anchor" href="#_3-4-全量微调-vs-参数高效微调-peft" aria-label="Permalink to “3.4 全量微调 vs 参数高效微调（PEFT）”">​</a></h3><p><strong>全量微调</strong>：更新模型的所有参数。效果上限最高，但代价大——需要存储完整模型的梯度和优化器状态，显存需求是模型权重本身的 4-5 倍。</p>',5)),n("p",null,[s[8]||(s[8]=n("strong",null,"参数高效微调（PEFT）",-1)),s[9]||(s[9]=a("：",-1)),e(p,{bold:"",type:"note"},{default:l(()=>[...s[7]||(s[7]=[a("只训练一小部分（通常是新增的）参数，冻结原始权重",-1)])]),_:1}),s[10]||(s[10]=a("。最常见的三种：",-1))]),s[22]||(s[22]=i(`<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LoRA (Low-Rank Adaptation):</span></span>
<span class="line"><span>  在原始权重旁增加两条低秩矩阵 A 和 B</span></span>
<span class="line"><span>  h = W·x + (B·A)·x</span></span>
<span class="line"><span>      ↑原始   ↑LoRA增量的修正（仅这部分可训练）</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  参数量: A + B 通常只有原始 W 的 0.1%~1%</span></span>
<span class="line"><span>  训练后: 可以将 (W + B·A) 合并为一个矩阵，推理速度无损</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  典型配置: r=8~64, α=16~128</span></span>
<span class="line"><span></span></span>
<span class="line"><span>QLoRA:</span></span>
<span class="line"><span>  LoRA + 4-bit 量化原始权重</span></span>
<span class="line"><span>  使得 70B 模型可以在 48GB 消费级 GPU 上微调</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Adapter:</span></span>
<span class="line"><span>  在 Transformer 层之间插入小型的 bottleneck 适配层</span></span>
<span class="line"><span>  每个 Adapter 参数量通常仅占原始模型的 1%~3%</span></span>
<span class="line"><span>  可以像插件一样为不同任务挂载不同的 Adapter</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div>`,1)),e(t,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/training-optimization/lora_fine_tuning.png",caption:""}),s[23]||(s[23]=i(`<blockquote><p>LoRA 就是咱们平民开发者的救星。它会把庞大的模型“冻结”起来，不让它的核心参数变动，只在旁边加一点点可以训练的小插件。</p><p>这样一来，以前需要一个机房才能完成的微调工作，现在一张显卡就能搞定。它用最省成本的方式，实现了最高效的模型定制化。</p></blockquote><p><strong>PEFT 为什么是工程主流？</strong></p><ul><li>7B 模型全量微调需要 ~60GB 显存（仅模型+优化器），LoRA 只需要 ~16GB</li><li>LoRA 训练出的 adapter 通常只有几 MB 到几十 MB，可以像文件一样分发和热切换</li><li>同一份基座模型可以挂载多个 LoRA adapter 服务不同任务</li></ul><h2 id="_4-sft-supervised-fine-tuning-监督微调" tabindex="-1">4. SFT（Supervised Fine-Tuning，监督微调） <a class="header-anchor" href="#_4-sft-supervised-fine-tuning-监督微调" aria-label="Permalink to “4. SFT（Supervised Fine-Tuning，监督微调）”">​</a></h2><p>SFT 是 Fine-Tuning 中最基础、最直观的形式：用<strong>指令-回答对</strong>作为监督信号，让模型学会按照人类期望的方式回应。</p><h3 id="_4-1-sft-的核心逻辑" tabindex="-1">4.1 SFT 的核心逻辑 <a class="header-anchor" href="#_4-1-sft-的核心逻辑" aria-label="Permalink to “4.1 SFT 的核心逻辑”">​</a></h3><p>预训练后的模型善于「续写」，但不太会「回答问题」。给它一个指令，它可能会续写下去而不是执行。SFT 正是解决这个问题——通过大量的指令-回答对训练，让模型学习「指令 → 回答」的行为模式，而不是「前缀 → 续写」。</p><h3 id="_4-2-instruction-数据的构建" tabindex="-1">4.2 Instruction 数据的构建 <a class="header-anchor" href="#_4-2-instruction-数据的构建" aria-label="Permalink to “4.2 Instruction 数据的构建”">​</a></h3><p>SFT 需要的是<strong>指令-回答对</strong>（Instruction-Response Pair）：</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;instruction&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;解释什么是光合作用，用小学生能听懂的语言&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;output&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;光合作用就像植物在给自己做饭。植物的叶子里有一种绿色的东西叫叶绿素，它能抓住阳光。植物用阳光作能量，把空气中的二氧化碳和从根部吸上来的水，变成自己的食物——葡萄糖，同时放出氧气。所以我们呼吸的氧气，很多都是植物送的礼物哦！&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>高质量 SFT 数据的关键特征：</p>`,11)),n("ul",null,[s[14]||(s[14]=n("li",null,[n("strong",null,"多样性"),a("：覆盖代码、写作、推理、翻译等多种任务，防止任务偏差（task bias）")],-1)),s[15]||(s[15]=n("li",null,[n("strong",null,"格式遵循"),a("：教会模型按照特定格式输出（JSON、Markdown 等）")],-1)),n("li",null,[s[12]||(s[12]=n("strong",null,"思维链",-1)),s[13]||(s[13]=a("：",-1)),e(p,{bold:"",type:"note"},{default:l(()=>[...s[11]||(s[11]=[a("对于推理类任务，需要包含详细的推理步骤（CoT），而不是只给最终答案",-1)])]),_:1})]),s[16]||(s[16]=n("li",null,[n("strong",null,"数量"),a("：通常几千到几万条高质量样本就足够——质量远比数量重要，1 万条精心制作的样本效果远超 10 万条低质数据")],-1))]),s[24]||(s[24]=i(`<p><strong>SFT 数据与 RLHF/DPO 数据的区别</strong>：</p><table tabindex="0"><thead><tr><th></th><th>SFT 数据</th><th>RLHF/DPO 数据</th></tr></thead><tbody><tr><td>形式</td><td>指令 + 单个标准答案</td><td>指令 + 多个候选回答的排序（偏好对）</td></tr><tr><td>标注难度</td><td>中等（需要写出高质量回答）</td><td>较低（只需要排序，不需从头写）</td></tr><tr><td>核心诉求</td><td>教会「怎么做」</td><td>教会「哪种做法更好」</td></tr><tr><td>典型量级</td><td>几千~几万条</td><td>几万~几十万条</td></tr></tbody></table><h3 id="_4-3-sft-在训练流水线中的位置" tabindex="-1">4.3 SFT 在训练流水线中的位置 <a class="header-anchor" href="#_4-3-sft-在训练流水线中的位置" aria-label="Permalink to “4.3 SFT 在训练流水线中的位置”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>预训练模型 —→ SFT —→ RLHF/DPO —→ 最终模型</span></span>
<span class="line"><span>  │              │         │</span></span>
<span class="line"><span>  │              │         └─ 对齐阶段：强化偏好，走向「更好」</span></span>
<span class="line"><span>  │              └─ 行为格式化：从续写到对话，学会格式</span></span>
<span class="line"><span>  └─ 知识积累：通读天下文字</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>SFT 承前启后</strong>：</p><ul><li>承接预训练的知识基础，并为后续的偏好对齐（RLHF/DPO）提供一个格式良好、行为可控的起点。</li><li>一个未经 SFT 的预训练模型直接丢进 RLHF，就像让一个从来没考过试的学生直接参加高考——他不知道答题格式，也不知道什么是「好的回答」。</li></ul><h2 id="_5-rlhf-基于人类反馈的强化学习" tabindex="-1">5. RLHF：基于人类反馈的强化学习 <a class="header-anchor" href="#_5-rlhf-基于人类反馈的强化学习" aria-label="Permalink to “5. RLHF：基于人类反馈的强化学习”">​</a></h2><p><strong>RLHF 是一种用强化学习方法将人类偏好注入模型行为的训练范式。</strong></p><p><strong>核心思路</strong>：先收集人类对模型输出质量的主观判断（偏好数据），再用这些偏好信号训练一个奖励模型来替代人类打分，最后用强化学习算法（PPO）优化模型策略，使模型生成的内容更符合人类期望——更有帮助、更安全、更诚实。</p>`,9)),e(t,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/training-optimization/rlhf_tips.png",caption:""}),s[25]||(s[25]=i(`<blockquote><p>若没有 RLHF，AI模型可能就是一个只会说话，但说话不好听、不好用的怪胎。</p><p>正是 RLHF，让 AI 变得有礼貌、好用，还符合咱们人类的价值观。</p><p><strong>具体怎么做呢？</strong></p><p>咱们让模型生成几个不同的回答，然后让人类来打分，哪个好、哪个不好，标得明明白白。久而久之，模型就摸清了“人类喜欢听什么、需要什么”，不再只是单纯地预测词语，而是学会了贴合人类的需求。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">一句话区分：</p><p><strong>SFT 教会模型「怎么回答问题」，RLHF 教会模型「什么样的回答才是好回答」。</strong></p><p>SFT 教会模型&quot;怎么回答&quot;，但无法精确控制回答的&quot;质量偏好&quot;——比如我们希望回答更有帮助、更安全、更诚实。RLHF 就是为此而生的。</p></div><h3 id="_5-1-完整流程" tabindex="-1">5.1 完整流程 <a class="header-anchor" href="#_5-1-完整流程" aria-label="Permalink to “5.1 完整流程”">​</a></h3><p>RLHF 通常包含三个步骤：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>阶段1: SFT (监督微调)</span></span>
<span class="line"><span>  预训练模型 ──→ 标注的高质量指令数据 ──→ SFT 模型</span></span>
<span class="line"><span>                                            │</span></span>
<span class="line"><span>阶段2: RM (奖励模型训练)                      │</span></span>
<span class="line"><span>  SFT 模型生成多个回答 ──→ 人工排序 ──→ 训练奖励模型</span></span>
<span class="line"><span>                                            │</span></span>
<span class="line"><span>阶段3: PPO (强化学习优化)                     │</span></span>
<span class="line"><span>  SFT 模型 ←── 奖励模型打分 ←── PPO 算法优化策略</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>步骤详解</strong>：</p><p>第一步（SFT）已在上节讲过。</p><p>第二步训练<strong>奖励模型（Reward Model, RM）</strong>。让 SFT 模型对同一个 prompt 生成多个不同回答，人工标注员进行排序（不是打分，是排序），然后用这些排序数据训练模型学会判断&quot;哪个回答更好&quot;：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>对同一个 prompt，模型生成 4 个回答:</span></span>
<span class="line"><span>  A: &quot;我认为...&quot;            (排名 2)</span></span>
<span class="line"><span>  B: &quot;根据相关法规...&quot;      (排名 1, 最好)</span></span>
<span class="line"><span>  C: &quot;这个问题没有意义&quot;     (排名 4, 最差)</span></span>
<span class="line"><span>  D: &quot;简单来说就是...&quot;      (排名 3)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 训练 RM 学习: score(B) &gt; score(A) &gt; score(D) &gt; score(C)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>第三步用 <strong>PPO（Proximal Policy Optimization）</strong> 算法进行强化学习：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>目标 = 奖励模型打分 - KL散度惩罚项</span></span>
<span class="line"><span></span></span>
<span class="line"><span>KL 惩罚项的作用: 防止模型&quot;跑偏&quot;</span></span>
<span class="line"><span>  - 如果新模型与 SFT 模型的输出分布差异太大，会被惩罚</span></span>
<span class="line"><span>  - 保证模型在&quot;变得更有帮助&quot;的同时不丢失基础能力</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_5-2-ppo-的核心思想" tabindex="-1">5.2 PPO 的核心思想 <a class="header-anchor" href="#_5-2-ppo-的核心思想" aria-label="Permalink to “5.2 PPO 的核心思想”">​</a></h3><p>PPO 的关键在于 &quot;Proximal&quot;（近端）——每次更新步子不要太大。PPO 通过<strong>裁剪（Clipping）</strong>机制来约束策略更新幅度：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PPO 裁剪目标:</span></span>
<span class="line"><span>  L = min( ratio × advantage,</span></span>
<span class="line"><span>           clip(ratio, 1-ε, 1+ε) × advantage )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>其中 ratio = 新策略概率 / 旧策略概率</span></span>
<span class="line"><span>     ε 通常取 0.1~0.2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>直觉: 如果 ratio 过大(策略变化太剧烈), 裁剪会限制它,</span></span>
<span class="line"><span>      防止一次不成功的更新破坏模型已有的好行为</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>RLHF 的代表性成果是 InstructGPT（ChatGPT 的前身）和 Claude。</p><h2 id="_6-dpo-direct-preference-optimization" tabindex="-1">6. DPO（Direct Preference Optimization） <a class="header-anchor" href="#_6-dpo-direct-preference-optimization" aria-label="Permalink to “6. DPO（Direct Preference Optimization）”">​</a></h2><p>RLHF 虽好，但流程复杂：需要训练一个独立奖励模型，需要运行 PPO（涉及 4 个模型：policy model、reference model、reward model、value model）。DPO 更简洁。</p><h3 id="_6-1-dpo-的核心思想" tabindex="-1">6.1 DPO 的核心思想 <a class="header-anchor" href="#_6-1-dpo-的核心思想" aria-label="Permalink to “6.1 DPO 的核心思想”">​</a></h3><p>DPO（2023）的关键洞察：<strong>可以直接从偏好数据中优化策略，不需要显式训练奖励模型</strong>。</p><p>数学上，DPO 证明了在 Bradley-Terry 偏好模型下，最优策略有一个闭式解。RLHF 的&quot;先拟合奖励模型再优化策略&quot;两步可以合成一步：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>RLHF:  偏好数据 → 训练RM → PPO优化策略  (两步)</span></span>
<span class="line"><span>DPO:   偏好数据 → 直接优化策略          (一步)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_6-2-dpo-与-rlhf-的对比" tabindex="-1">6.2 DPO 与 RLHF 的对比 <a class="header-anchor" href="#_6-2-dpo-与-rlhf-的对比" aria-label="Permalink to “6.2 DPO 与 RLHF 的对比”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>RLHF</th><th>DPO</th></tr></thead><tbody><tr><td>需要奖励模型</td><td>是（需单独训练）</td><td>否</td></tr><tr><td>训练稳定性</td><td>需要大量调参</td><td>类似 SFT，更稳定</td></tr><tr><td>计算开销</td><td>高（PPO 需 4 个模型）</td><td>低（只需 2 个模型）</td></tr><tr><td>在线/离线</td><td>通常需要在线采样</td><td>纯离线</td></tr><tr><td>工程复杂度</td><td>高</td><td>低</td></tr><tr><td>最终效果</td><td>成熟，广泛验证</td><td>接近 RLHF，某些情况下更优</td></tr></tbody></table><p>DPO 的损失函数简洁优雅：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>L_DPO = -E[ log σ( β × (log π_θ(y_w|x) / π_ref(y_w|x)</span></span>
<span class="line"><span>                        - log π_θ(y_l|x) / π_ref(y_l|x)) ) ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>直觉: 增大&quot;好回答&quot;相对于参考模型的概率，</span></span>
<span class="line"><span>      减小&quot;差回答&quot;相对于参考模型的概率</span></span>
<span class="line"><span>      β 控制偏离参考模型的程度</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>DPO 让偏好对齐变得像 SFT 一样简单——同样的训练循环，只是换了个损失函数。</p><h2 id="_7-grpo-group-relative-policy-optimization" tabindex="-1">7. GRPO（Group Relative Policy Optimization） <a class="header-anchor" href="#_7-grpo-group-relative-policy-optimization" aria-label="Permalink to “7. GRPO（Group Relative Policy Optimization）”">​</a></h2><p>GRPO 是 DeepSeek-R1 采用的强化学习训练方法，在 2025 年初引起广泛关注。</p><h3 id="_7-1-核心创新" tabindex="-1">7.1 核心创新 <a class="header-anchor" href="#_7-1-核心创新" aria-label="Permalink to “7.1 核心创新”">​</a></h3><p>传统 PPO 需要一个独立的 Value Model 来估计优势函数，增加了显存和计算开销。GRPO 的做法是<strong>对同一个 prompt 生成一组候选回答，用组内相对分数代替价值模型</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PPO:   对每个生成样本, 需要 Value Model 估计 baseline</span></span>
<span class="line"><span>       → 需要额外训练和维护一个与 policy 同量级的模型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GRPO:  对同一个 prompt, 同时采样 G 个回答</span></span>
<span class="line"><span>       → 用组内平均奖励作为 baseline</span></span>
<span class="line"><span>       → advantage_i = (reward_i - mean(rewards)) / std(rewards)</span></span>
<span class="line"><span>       → 不需要 Value Model!</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GRPO 工作流:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Prompt ──→ 模型采样 G 个回答</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>              ├─→ 回答1 → 奖励模型打分: 0.8</span></span>
<span class="line"><span>              ├─→ 回答2 → 奖励模型打分: 0.3</span></span>
<span class="line"><span>              ├─→ 回答3 → 奖励模型打分: 0.6</span></span>
<span class="line"><span>              └─→ 回答4 → 奖励模型打分: 0.9</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>        组内均值 = 0.65, 标准差 = 0.24</span></span>
<span class="line"><span>              │</span></span>
<span class="line"><span>        相对优势:</span></span>
<span class="line"><span>          回答1: (0.8-0.65)/0.24 = +0.63  ← 好, 强化</span></span>
<span class="line"><span>          回答2: (0.3-0.65)/0.24 = -1.46  ← 差, 削弱</span></span>
<span class="line"><span>          回答3: (0.6-0.65)/0.24 = -0.21  ← 一般</span></span>
<span class="line"><span>          回答4: (0.9-0.65)/0.24 = +1.04  ← 最好, 强化</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h3 id="_7-2-与-ppo-dpo-的差异" tabindex="-1">7.2 与 PPO/DPO 的差异 <a class="header-anchor" href="#_7-2-与-ppo-dpo-的差异" aria-label="Permalink to “7.2 与 PPO/DPO 的差异”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>PPO</th><th>DPO</th><th>GRPO</th></tr></thead><tbody><tr><td>价值模型</td><td>需要</td><td>不需要</td><td>不需要</td></tr><tr><td>参考模型</td><td>需要</td><td>需要</td><td>需要</td></tr><tr><td>数据需求</td><td>在线采样</td><td>离线偏好对</td><td>在线采样</td></tr><tr><td>相对比较</td><td>与baseline</td><td>偏好对</td><td>组内比较</td></tr><tr><td>显存效率</td><td>低</td><td>高</td><td>中</td></tr><tr><td>代表应用</td><td>ChatGPT/Claude</td><td>Llama 3/Zephyr</td><td>DeepSeek R1</td></tr></tbody></table><p>GRPO 在 DeepSeek-R1 中被用来激发<strong>推理能力</strong>（reasoning emergence）。通过精心设计的奖励规则（格式奖励 + 正确性奖励），模型在 RL 过程中自发学会了&quot;反思&quot;和&quot;多步验证&quot;等行为——即著名的 &quot;aha moment&quot;。</p><h2 id="_8-instruction-tuning-指令微调" tabindex="-1">8. Instruction Tuning：指令微调 <a class="header-anchor" href="#_8-instruction-tuning-指令微调" aria-label="Permalink to “8. Instruction Tuning：指令微调”">​</a></h2><p>Instruction Tuning 是 SFT 的一种特定形式，专注于让模型<strong>理解并遵循自然语言指令</strong>。</p><p>典型的 Instruction Tuning 数据格式：</p><div class="language-markdown line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Instruction:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">将以下英语翻译成中文</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Input:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The quick brown fox jumps over the lazy dog.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Response:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">那只敏捷的棕色狐狸跳过了那只懒狗。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>关键实践</strong>：</p><ul><li><strong>多任务混合</strong>：将不同任务（翻译、推理、代码、写作等）的指令数据混合训练，效果远好于单一任务微调（FLAN 论文的核心发现）</li><li><strong>零样本泛化</strong>：Instruction Tuning 后模型能在未见过的任务类型上表现出色</li><li><strong>数据多样性 &gt; 数据量</strong>：用 1000 个高质量、多样化的任务训练，效果好于用 10000 个同质化任务</li></ul><h2 id="_9-alignment-价值对齐" tabindex="-1">9. Alignment：价值对齐 <a class="header-anchor" href="#_9-alignment-价值对齐" aria-label="Permalink to “9. Alignment：价值对齐”">​</a></h2><p>技术能力只是硬币的一面，另一面是<strong>让模型的行为符合人类价值观</strong>。</p><h3 id="_9-1-hhh-原则" tabindex="-1">9.1 HHH 原则 <a class="header-anchor" href="#_9-1-hhh-原则" aria-label="Permalink to “9.1 HHH 原则”">​</a></h3><p>Anthropic 提出了对齐的三个核心维度：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  HHH 原则                            │</span></span>
<span class="line"><span>├───────────────┬─────────────────────────────────────┤</span></span>
<span class="line"><span>│ Helpful       │ 回答应该有实际帮助，解决用户问题     │</span></span>
<span class="line"><span>│ (有帮助的)    │ 必要时主动澄清模糊问题               │</span></span>
<span class="line"><span>├───────────────┼─────────────────────────────────────┤</span></span>
<span class="line"><span>│ Harmless      │ 拒绝有害请求（制作武器、仇恨言论等） │</span></span>
<span class="line"><span>│ (无害的)      │ 避免生成歧视性、误导性内容           │</span></span>
<span class="line"><span>├───────────────┼─────────────────────────────────────┤</span></span>
<span class="line"><span>│ Honest        │ 不知道就说不知道，不编造             │</span></span>
<span class="line"><span>│ (诚实的)      │ 准确反映自身能力和局限               │</span></span>
<span class="line"><span>└───────────────┴─────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>这三个维度有时存在<strong>张力</strong>。例如，一个无害的拒绝（&quot;我不能回答这个问题&quot;）可能不是最有帮助的回应。对齐在三者之间寻找平衡。</p><h3 id="_9-2-constitutional-ai" tabindex="-1">9.2 Constitutional AI <a class="header-anchor" href="#_9-2-constitutional-ai" aria-label="Permalink to “9.2 Constitutional AI”">​</a></h3><p>Constitutional AI（宪法式 AI）是 Anthropic 提出的方法：<strong>用一套原则（宪法）来指导模型行为，而不是依赖大量人工标注</strong>。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>阶段1: 监督学习阶段</span></span>
<span class="line"><span>  1. 用 red-teaming prompts 让模型生成有害回答</span></span>
<span class="line"><span>  2. 要求模型根据宪法原则修改自己的回答</span></span>
<span class="line"><span>  3. 用修正后的回答做 SFT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段2: RL 阶段 (RLAIF — RL from AI Feedback)</span></span>
<span class="line"><span>  1. 模型根据宪法原则评估自己的回答</span></span>
<span class="line"><span>  2. 用 AI 反馈替代人工反馈进行 RL</span></span>
<span class="line"><span>  3. 整个过程中人类反馈的角色被宪法原则取代</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>宪法原则示例：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>原则: &quot;选择毒性最小的回答。如果一组回答中有回答包含</span></span>
<span class="line"><span>       侮辱、威胁或贬低性语言，即使其他回答似乎更有帮助，</span></span>
<span class="line"><span>       也应选择最尊重他人的那个。&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Constitutional AI 的美妙之处在于<strong>可扩展性</strong>：一旦定义好宪法原则，就可以用 AI 自己生成训练数据，大幅减少对人工标注的依赖。Claude 系列模型正是用这种方法训练的。</p>`,53))]))}});export{T as __pageData,v as default};
